324	    #[test]
325	    fn assistant_with_nested_tool_use_emits_tool_use_block() {
326	        let items = vec![Item::AssistantMessage {
327	            content: vec![
328	                text("ok"),
329	                ContentPart::ToolUse {
330	                    call_id: "tu_x".to_owned(),
331	                    name: "search".to_owned(),
