381	    /// SMA-804: a checkpoint `Inject` leaves a tool result directly followed
382	    /// by a user message. The translator folds both into one user turn.
383	    #[test]
384	    fn tool_result_then_user_message_request_shape() {
385	        let items = vec![
386	            Item::UserMessage {
387	                content: vec![text("start")],
388	            },
389	            Item::AssistantMessage {
390	                content: vec![text("calling")],
391	                agent: None,
392	            },
393	            Item::ToolCall {
394	                call_id: "tu_1".to_owned(),
395	                name: "ping".to_owned(),
396	                args: json!({}),
397	            },
398	            Item::ToolResult {
399	                call_id: "tu_1".to_owned(),
400	                content: vec![text("pong")],
401	            },
402	            Item::UserMessage {
403	                content: vec![text("news")],
404	            },
405	        ];
406	        let out = translate_messages(&items);
407	        assert_eq!(
408	            out.messages,
409	            json!([
410	                {"role": "user", "content": [{"type": "text", "text": "start"}]},
411	                {"role": "assistant", "content": [
412	                    {"type": "text", "text": "calling"},
413	                    {"type": "tool_use", "id": "tu_1", "name": "ping", "input": {}},
414	                ]},
415	                {"role": "user", "content": [
416	                    {"type": "tool_result", "tool_use_id": "tu_1", "content": "pong"},
417	                    {"type": "text", "text": "news"},
418	                ]},
